{
  "title": "Responsibility for the Iraq dossier",
  "setting": "United Kingdom Government, September 2002; Joint Intelligence Committee dossier on Iraq.",
  "decider": "The Security and Intelligence Co-ordinator and the Chairman of the JIC, with Government agreement",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The Security and Intelligence Co-ordinator and the Chairman of the JIC",
  "agent_role": "decide",
  "situation": "The Government was preparing to publish a dossier drawing on intelligence about Iraq. The JIC’s leadership considered whether the JIC or another part of Government should take responsibility for producing and owning it. Government witnesses considered JIC endorsement important to the dossier’s credibility, while the Government also intended to use the document in advocacy of its policy. The JIC’s role was to offer a dispassionate assessment, not to make a case for a policy. Its leadership wanted the dossier to reflect intelligence-community judgments and not prejudice national security. Presenting intelligence judgments to a wider public audience was a difficult task that could put pressure on the JIC’s neutral assessment standards.",
  "question": "What should the Security and Intelligence Co-ordinator and the Chairman of the JIC do about responsibility for producing and owning the dossier?",
  "facts": [
    {
      "id": "F1",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The Government had decided to publish a dossier drawing on intelligence.",
      "spans": [
        "src:324c69de5486#p92.4"
      ]
    },
    {
      "id": "F2",
      "kind": "authority",
      "status": "assessed",
      "fact": "The Security and Intelligence Co-ordinator and the JIC Chairman considered JIC responsibility appropriate for reflecting intelligence-community judgments and avoiding prejudice to national security.",
      "spans": [
        "src:324c69de5486#p92.4"
      ]
    },
    {
      "id": "F3",
      "kind": "situation",
      "status": "assessed",
      "fact": "Many ministerial and official witnesses considered that a Government document claiming intelligence support would face immediate skepticism without evident JIC endorsement.",
      "spans": [
        "src:324c69de5486#p92.5"
      ]
    },
    {
      "id": "F4",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Government information about Al Qaida’s responsibility for the September 11 attacks had been published without public reference to the JIC, and that issue had less controversy and skepticism about the grounds for Government policy.",
      "spans": [
        "src:324c69de5486#p92.6"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "assessed",
      "fact": "Associating the JIC’s name with the dossier was seen as lending it objectivity and credibility.",
      "spans": [
        "src:324c69de5486#p92.7",
        "src:324c69de5486#p92.8"
      ]
    },
    {
      "id": "F6",
      "kind": "situation",
      "status": "assessed",
      "fact": "The Government intended the dossier to provide intelligence-based information about Iraq and to encourage international recognition of the issue’s importance.",
      "spans": [
        "src:324c69de5486#p93.2",
        "src:324c69de5486#p93.3",
        "src:324c69de5486#p93.5"
      ]
    },
    {
      "id": "F7",
      "kind": "situation",
      "status": "assessed",
      "fact": "The JIC Chairman understood the dossier’s purpose as informing public debate with intelligence assessments, not making a case for anything.",
      "spans": [
        "src:324c69de5486#p93.6",
        "src:324c69de5486#p93.7",
        "src:324c69de5486#p93.9"
      ]
    },
    {
      "id": "F8",
      "kind": "capability",
      "status": "assessed",
      "fact": "The JIC’s assessment concerned Iraqi nuclear, biological, chemical, and ballistic missile programmes and relied substantially on judgment; presenting those judgments to a wider public was a different and difficult task that could strain neutral, objective standards.",
      "spans": [
        "src:324c69de5486#p93.10"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The JIC retains responsibility for producing and owning the dossier.",
      "move": "act",
      "disposition": "retain",
      "irreversible": false
    },
    "O2": {
      "do": "The JIC relinquishes responsibility for producing and owning the dossier to another Government department.",
      "move": "act",
      "disposition": "relinquish",
      "irreversible": false
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "real_option": "O1",
  "authored_options": [
    "O2"
  ],
  "no_opposite_reason": ""
}

